//! P8-M1-T02 integration tests: the vault object model
//! (item / revision / file / relationship / context), our-own-format serde, and
//! the structural validation rules.
//!
//! The canonical example vault is byte-locked to the committed golden
//! `tests/golden/example-vault.oepvault.json` (generated by THIS crate via the
//! `OEP_VAULT_REGEN=1` regen test), and independently re-parsed from the other
//! side by `tests/test_p8_vault_object_model.py` (stdlib Python), which also
//! recomputes every file's sha-256 from the committed fixture blobs and checks
//! it against the golden's `blob_sha256` values -- the content-addressed,
//! hash-verified acceptance on real material.

use oep_pdm::model::{
    Context, File, ImportLedger, Item, Origin, Ref, Relationship, Revision, RevisionOrigin,
    VaultDoc, REL_KIND_COMPOSED_OF, REL_KIND_DERIVED_FROM, REL_KIND_REFERENCES,
    REL_KIND_SUPERSEDES,
};
use oep_pdm::validate::ValidationError;

const GOLDEN_PATH: &str = "tests/golden/example-vault.oepvault.json";
const GOLDEN: &str = include_str!("golden/example-vault.oepvault.json");

/// The V5-era folder tree `W:\Data\Baja` was imported (P10-M1-T03) and then
/// one item got a later save-revision. Content addresses are the REAL sha-256
/// of the committed fixture blobs under `tests/fixtures/legacy/`.
const SHA_REAR_FRAME: &str = "464128cdb789e49d87a4b96acc6544422dbc14de8a2f8dba39db2474546cfa6e";
const SHA_REAR_FRAME_V2: &str = "096ccc955537e07cff614128f03c263ba93138013decc4100e3a07c159385efb";
const SHA_SKID_PLATE: &str = "b430c157a712fa1c5d2935febe34e3f5cbdb8b1765053edcc7d006a2fc4ba347";
const SHA_BAJA_CHASSIS: &str = "a627626445c2769cbcdb02be31f60798a08145ad7e223c39285beae9d9e7805e";
const SHA_README: &str = "6fd81c36654b123fe11c7ce4073b082c80d02c52f194c0986dd91d19f54f4569";
const SHA_DRIVELINE: &str = "3ec212c2bc1df7543669e5065d74c5084f3d784e4a262ab36052d718c4e4be75";

/// RFC 3339, deterministic (golden is byte-stable).
const T0: &str = "2026-10-17T00:00:00Z";
const T1: &str = "2026-10-17T01:02:03Z";
const IMPORTER: &str = "oep-vault-migrate/0.1";

/// Builds the canonical example: a `Baja` product vault whose items come from
/// the imported V5-era tree `W:\Data\Baja` plus one `pdm-save` revision, with
/// every model class exercised and real content addresses.
pub fn build_example() -> VaultDoc {
    let mut doc = VaultDoc::new();

    // Contexts: the imported directory tree, root first.
    doc.push_context(
        Context::new("ctx-baja", "Baja", "product")
            .with_note("V5-era folder tree root imported by P10-M1-T03"),
    );
    doc.push_context(Context::new("ctx-chassis", "Chassis", "folder").with_parent("ctx-baja"));
    doc.push_context(Context::new("ctx-frame", "Frame", "folder").with_parent("ctx-chassis"));
    doc.push_context(Context::new("ctx-docs", "Docs", "folder").with_parent("ctx-baja"));
    doc.push_context(Context::new("ctx-driveline", "Driveline", "folder").with_parent("ctx-docs"));

    // Items (one per imported file).
    doc.push_item(
        Item::new("item-rear-frame", "RearFrame", "part")
            .with_context("ctx-frame")
            .with_part_number("ISO-REAR-001")
            .with_created_at(T0)
            .with_origin(Origin::v5_folder_tree(
                "W:\\Data\\Baja\\Chassis\\Frame\\RearFrame.CATPart",
                T0,
                Some(SHA_REAR_FRAME.to_string()),
                IMPORTER,
            )),
    );
    doc.push_item(
        Item::new("item-skid-plate", "SkidPlate", "part")
            .with_context("ctx-frame")
            .with_part_number("ISO-SKD-002")
            .with_created_at(T0)
            .with_origin(Origin::v5_folder_tree(
                "W:\\Data\\Baja\\Chassis\\Frame\\SkidPlate.CATPart",
                T0,
                Some(SHA_SKID_PLATE.to_string()),
                IMPORTER,
            )),
    );
    doc.push_item(
        Item::new("item-baja-chassis", "BajaChassis", "assembly")
            .with_context("ctx-chassis")
            .with_part_number("ISO-CHS-003")
            .with_created_at(T0)
            .with_origin(Origin::v5_folder_tree(
                "W:\\Data\\Baja\\Chassis\\BajaChassis.CATProduct",
                T0,
                Some(SHA_BAJA_CHASSIS.to_string()),
                IMPORTER,
            )),
    );
    doc.push_item(
        Item::new("item-readme", "Readme", "document")
            .with_context("ctx-docs")
            .with_created_at(T0)
            .with_origin(Origin::v5_folder_tree(
                "W:\\Data\\Baja\\Docs\\Readme.txt",
                T0,
                Some(SHA_README.to_string()),
                IMPORTER,
            )),
    );
    doc.push_item(
        Item::new("item-driveline-notes", "DrivelineNotes", "document")
            .with_context("ctx-driveline")
            .with_created_at(T0)
            .with_origin(Origin::v5_folder_tree(
                "W:\\Data\\Baja\\Docs\\Driveline\\DrivelineNotes.txt",
                T0,
                Some(SHA_DRIVELINE.to_string()),
                IMPORTER,
            )),
    );

    // Files (content-addressed by the real fixture-bytes sha-256).
    doc.push_file(
        File::new(
            "file-rear-frame",
            "RearFrame.CATPart",
            "catpart",
            SHA_REAR_FRAME,
        )
        .with_size(35),
    );
    doc.push_file(
        File::new(
            "file-rear-frame-v2",
            "RearFrame-v2.CATPart",
            "catpart",
            SHA_REAR_FRAME_V2,
        )
        .with_size(60),
    );
    doc.push_file(
        File::new(
            "file-skid-plate",
            "SkidPlate.CATPart",
            "catpart",
            SHA_SKID_PLATE,
        )
        .with_size(35),
    );
    doc.push_file(
        File::new(
            "file-baja-chassis",
            "BajaChassis.CATProduct",
            "catproduct",
            SHA_BAJA_CHASSIS,
        )
        .with_size(40),
    );
    doc.push_file(File::new("file-readme", "Readme.txt", "txt", SHA_README).with_size(36));
    doc.push_file(
        File::new(
            "file-driveline-notes",
            "DrivelineNotes.txt",
            "txt",
            SHA_DRIVELINE,
        )
        .with_size(23),
    );

    // Revisions. Row 1 of every imported item is a v5-folder-tree revision;
    // RearFrame's row 2 is a later ordinary PDM save.
    doc.push_revision(
        Revision::new(
            "rev-rear-frame-1",
            "item-rear-frame",
            "1",
            "working",
            IMPORTER,
        )
        .with_created_at(T0)
        .with_file("file-rear-frame")
        .with_origin(RevisionOrigin::v5_folder_tree(
            "W:\\Data\\Baja\\Chassis\\Frame\\RearFrame.CATPart",
        )),
    );
    doc.push_revision(
        Revision::new(
            "rev-rear-frame-2",
            "item-rear-frame",
            "2",
            "working",
            "oep-modeler",
        )
        .with_created_at(T1)
        .with_file("file-rear-frame-v2")
        .with_origin(RevisionOrigin::pdm_save()),
    );
    doc.push_revision(
        Revision::new(
            "rev-skid-plate-1",
            "item-skid-plate",
            "1",
            "working",
            IMPORTER,
        )
        .with_created_at(T0)
        .with_file("file-skid-plate")
        .with_origin(RevisionOrigin::v5_folder_tree(
            "W:\\Data\\Baja\\Chassis\\Frame\\SkidPlate.CATPart",
        )),
    );
    doc.push_revision(
        Revision::new(
            "rev-baja-chassis-1",
            "item-baja-chassis",
            "1",
            "working",
            IMPORTER,
        )
        .with_created_at(T0)
        .with_file("file-baja-chassis")
        .with_origin(RevisionOrigin::v5_folder_tree(
            "W:\\Data\\Baja\\Chassis\\BajaChassis.CATProduct",
        )),
    );
    doc.push_revision(
        Revision::new("rev-readme-1", "item-readme", "1", "working", IMPORTER)
            .with_created_at(T0)
            .with_file("file-readme")
            .with_origin(RevisionOrigin::v5_folder_tree(
                "W:\\Data\\Baja\\Docs\\Readme.txt",
            )),
    );
    doc.push_revision(
        Revision::new(
            "rev-driveline-notes-1",
            "item-driveline-notes",
            "1",
            "working",
            IMPORTER,
        )
        .with_created_at(T0)
        .with_file("file-driveline-notes")
        .with_origin(RevisionOrigin::v5_folder_tree(
            "W:\\Data\\Baja\\Docs\\Driveline\\DrivelineNotes.txt",
        )),
    );

    // Relationships: BOM composition, a document reference, a supersede, and a
    // derived-from lineage (every relationship kind is exercised).
    doc.push_relationship(
        Relationship::new(
            REL_KIND_COMPOSED_OF,
            Ref::item("item-baja-chassis"),
            Ref::item("item-rear-frame"),
        )
        .with_id("rel-bom-1")
        .with_note("chassis composes the rear frame"),
    );
    doc.push_relationship(
        Relationship::new(
            REL_KIND_COMPOSED_OF,
            Ref::item("item-baja-chassis"),
            Ref::item("item-skid-plate"),
        )
        .with_id("rel-bom-2"),
    );
    doc.push_relationship(
        Relationship::new(
            REL_KIND_REFERENCES,
            Ref::item("item-readme"),
            Ref::item("item-baja-chassis"),
        )
        .with_id("rel-ref-1")
        .with_note("import notes cite the product"),
    );
    doc.push_relationship(
        Relationship::new(
            REL_KIND_SUPERSEDES,
            Ref::revision("rev-rear-frame-2"),
            Ref::revision("rev-rear-frame-1"),
        )
        .with_id("rel-sup-1"),
    );
    doc.push_relationship(
        Relationship::new(
            REL_KIND_DERIVED_FROM,
            Ref::revision("rev-driveline-notes-1"),
            Ref::revision("rev-readme-1"),
        )
        .with_id("rel-der-1")
        .with_note("driveline notes derived from the readme"),
    );

    // Import ledger: one row for the folder-tree migration.
    doc.push_import(ImportLedger {
        kind: "v5-folder-tree".to_string(),
        root_legacy_path: "W:\\Data\\Baja".to_string(),
        imported_at: T0.to_string(),
        importer: IMPORTER.to_string(),
        contexts: 5,
        items: 5,
        files: 5,
        blobs: 5,
        keys: vec![
            "Chassis/Frame/RearFrame.CATPart".into(),
            "Chassis/Frame/SkidPlate.CATPart".into(),
            "Chassis/BajaChassis.CATProduct".into(),
            "Docs/Readme.txt".into(),
            "Docs/Driveline/DrivelineNotes.txt".into(),
        ],
    });

    doc
}

// ---------------------------------------------------------------------------
// snapshot: the serializer is byte-locked to the committed golden
// ---------------------------------------------------------------------------

#[test]
fn serializer_snapshot_matches_committed_golden() {
    let text = build_example().to_json_pretty().expect("serialize");
    assert_eq!(text, GOLDEN, "serializer drifted from committed golden");
}

/// One-shot generator for the committed golden (run manually):
/// `OEP_VAULT_REGEN=1 cargo test -p oep-pdm --test vault_model_golden regenerate_golden`
#[test]
fn regenerate_golden() {
    match std::env::var("OEP_VAULT_REGEN") {
        Ok(v) if v == "1" => {
            let text = build_example().to_json_pretty().expect("serialize");
            std::fs::write(GOLDEN_PATH, text).expect("write golden");
            eprintln!("wrote {GOLDEN_PATH}");
        }
        _ => eprintln!("skip: set OEP_VAULT_REGEN=1 to (re)generate the golden"),
    }
}

// ---------------------------------------------------------------------------
// round-trip identity and clean validation of the golden
// ---------------------------------------------------------------------------

#[test]
fn serialize_then_deserialize_is_identity() {
    let original = build_example();
    let text = original.to_json_pretty().expect("serialize");
    let back = VaultDoc::from_json_pretty(&text).expect("deserialize");
    assert_eq!(back, original);
}

#[test]
fn golden_roundtrips_and_validates_clean() {
    let doc = VaultDoc::from_json_pretty(GOLDEN).expect("parse committed golden");
    assert_eq!(doc.format(), "oep-vault");
    assert_eq!(doc.version(), 1);
    assert!(
        doc.validate().is_empty(),
        "unexpected issues: {:?}",
        doc.validate()
    );
    assert_eq!(doc.contexts.len(), 5);
    assert_eq!(doc.items.len(), 5);
    assert_eq!(doc.revisions.len(), 6);
    assert_eq!(doc.files.len(), 6);
    assert_eq!(doc.relationships.len(), 5);
    assert_eq!(doc.imports.len(), 1);
}

#[test]
fn where_used_primitives_on_golden() {
    let doc = build_example();
    assert_eq!(
        doc.components_of("item-baja-chassis"),
        vec!["item-rear-frame".to_string(), "item-skid-plate".to_string(),]
    );
    assert_eq!(
        doc.where_used("item-rear-frame"),
        vec!["item-baja-chassis".to_string()]
    );
    assert_eq!(doc.where_used("item-baja-chassis"), Vec::<String>::new());
}

// ---------------------------------------------------------------------------
// validation: each rule rejects a broken document
// ---------------------------------------------------------------------------

fn codes(errors: Vec<ValidationError>) -> Vec<&'static str> {
    let mut v: Vec<&'static str> = errors.iter().map(|e| e.code).collect();
    v.sort_unstable();
    v
}

#[test]
fn validate_rejects_duplicate_id() {
    let mut doc = build_example();
    doc.push_item(Item::new("item-rear-frame", "RearFrame-again", "part")); // collides
    assert!(codes(doc.validate()).contains(&"duplicate-id"));
}

#[test]
fn validate_rejects_unresolved_context() {
    let mut doc = build_example();
    doc.items[0].context_id = Some("ctx-ghost".to_string());
    assert!(codes(doc.validate()).contains(&"unresolved-context"));
}

#[test]
fn validate_rejects_unresolved_file() {
    let mut doc = build_example();
    doc.revisions[0].file_ids.push("file-ghost".to_string());
    assert!(codes(doc.validate()).contains(&"unresolved-file"));
}

#[test]
fn validate_rejects_invalid_blob_address() {
    let mut doc = build_example();
    doc.files[0].blob_sha256 = "not-a-sha".to_string();
    assert!(codes(doc.validate()).contains(&"invalid-blob-address"));
    // 64 chars but not lowercase hex / not hex at all is also rejected.
    let mut doc2 = build_example();
    doc2.files[0].blob_sha256 = "G".repeat(64);
    assert!(codes(doc2.validate()).contains(&"invalid-blob-address"));
}

#[test]
fn validate_rejects_invalid_revision_state() {
    let mut doc = build_example();
    doc.revisions[0].state = "shipped".to_string();
    assert!(codes(doc.validate()).contains(&"invalid-revision-state"));
}

#[test]
fn validate_rejects_context_cycle() {
    let mut doc = build_example();
    // ctx-baja (index 0) parent -> ctx-chassis, and ctx-chassis parent -> ctx-baja.
    doc.contexts[0].parent_id = Some("ctx-chassis".to_string());
    assert!(codes(doc.validate()).contains(&"context-cycle"));
}

#[test]
fn validate_rejects_folder_without_parent() {
    let mut doc = build_example();
    doc.contexts[1].parent_id = None; // ctx-chassis is a folder
    assert!(codes(doc.validate()).contains(&"root-folder"));
}

#[test]
fn validate_rejects_bad_relationship_kind_usage() {
    // composed_of with a revision endpoint.
    let mut doc = build_example();
    doc.push_relationship(
        Relationship::new(
            REL_KIND_COMPOSED_OF,
            Ref::item("item-baja-chassis"),
            Ref::revision("rev-rear-frame-1"),
        )
        .with_id("rel-bad-1"),
    );
    assert!(codes(doc.validate()).contains(&"relationship-kind-mismatch"));

    // supersedes joining revisions of different items.
    let mut doc2 = build_example();
    doc2.push_relationship(
        Relationship::new(
            REL_KIND_SUPERSEDES,
            Ref::revision("rev-rear-frame-2"),
            Ref::revision("rev-skid-plate-1"),
        )
        .with_id("rel-bad-2"),
    );
    assert!(codes(doc2.validate()).contains(&"relationship-kind-mismatch"));
}

#[test]
fn validate_rejects_unresolved_relationship_endpoint() {
    let mut doc = build_example();
    doc.push_relationship(
        Relationship::new(
            REL_KIND_DERIVED_FROM,
            Ref::item("item-rear-frame"),
            Ref::item("item-ghost"),
        )
        .with_id("rel-bad-3"),
    );
    assert!(codes(doc.validate()).contains(&"bad-relationship"));
}

#[test]
fn tolerates_unknown_optional_metadata_on_load() {
    // Forward-compat within version 1: unknown extra JSON keys are ignored by
    // serde (the schema adds optional fields, old vaults stay readable).
    let doc = VaultDoc::from_json_pretty(
        r#"{"format":"oep-vault","version":1,"items":[{"id":"i1","name":"X","kind":"part","created_at":"2026-10-17T00:00:00Z","future_field":42}]}"#,
    )
    .expect("extra field tolerated");
    assert_eq!(doc.items.len(), 1);
}
